import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {createRequire} from 'node:module';
const require=createRequire(new URL('../runtime/package.json',import.meta.url));
const {JSDOM}=require('jsdom');
const code=await fs.readFile(new URL('../public/document-study/folder-browser.js',import.meta.url),'utf8');
const source=(id,title=id,kind='note')=>({id,title,kind,rel_path:title+'.md'});
const view=(sources=[])=>({schema:'ar-create.library-folders.v1',domain:'library',revision:1,indexHash:'hash1',folders:[{id:'a',name:'Parent',parentId:null,sourceIds:['s1']},{id:'b',name:'Child',parentId:'a',sourceIds:['s1','s2']}],sources,undoOperationId:'undo1'});
async function setup(data=view([source('s1','Alpha'),source('s2','Beta')]),post,{actualWork=false}={}){
 const dom=new JSDOM('<body><div id="app"><div id="workspace"><h2 class="c3-ctitle">Library</h2><div id="original"><textarea>Unsaved words</textarea></div></div></div></body>',{runScripts:'outside-only',url:'http://localhost/'}),w=dom.window,calls=[];
 w.AR_CREATE_REVIEW_MODE={actualWork};w.current=()=>({view:'record',viewedStage:1});w.matchMedia=()=>({matches:false});w.c3Shell={register(_name,fn){this.install=fn;}};w.c3Workbench={registerPanel(){},decorate(){},toggle(){}};
 w.fetch=async(url,opts={})=>{calls.push({url,opts});if(opts.method==='POST')return post?post(url,opts):{ok:true,json:async()=>({...data,revision:2,indexHash:'hash2'})};return {ok:true,json:async()=>data};};
 w.eval(await fs.readFile(new URL('../public/document-study/display-format.js',import.meta.url),'utf8'));w.eval(code);await w.workbenchFolderBrowser.refresh();const initialBrowser=!!w.document.querySelector('.wfb-browser');w.workbenchFolderBrowser.panelSpec('library').press('all');return {w,d:w.document,calls,initialBrowser,close:()=>w.close()};
}
test('recursive source counts are unique; nested folder lists include descendants',async()=>{const x=await setup();try{const spec=x.w.workbenchFolderBrowser.panelSpec('library');assert.match(spec.body(spec.rows()),/Parent/);spec.press('folder:a');assert.equal(x.d.querySelector('.wfb-count').textContent,'2');assert.equal(x.d.querySelector('.wfb-count').getAttribute('aria-label'),'2 shown of 2 sources');assert.equal(x.d.querySelectorAll('.wfb-vrow').length,2);}finally{x.close();}});
test('2000 real sources render a bounded window and scrolling reaches final row',async()=>{const x=await setup(view(Array.from({length:2000},(_,i)=>source('s'+i,String(i).padStart(4,'0')))));try{enterSelection(x);assert.ok(x.d.querySelectorAll('.wfb-vrow').length<50);const list=x.d.querySelector('.wfb-vt');list.scrollTop=1990*36;list.dispatchEvent(new x.w.Event('scroll'));assert.ok([...x.d.querySelectorAll('.wfb-title')].some(n=>n.textContent==='1999'));}finally{x.close();}});
function enterSelection(x){if(!x.d.querySelector('[data-wfb-select]'))x.d.querySelector('[data-wfb-action=selectionmode]').click();}
function mountFolderPanel(x){const spec=x.w.workbenchFolderBrowser.panelSpec('library'),panel=x.d.createElement('aside');panel.innerHTML=spec.body(spec.rows());x.d.body.append(panel);spec.afterRender(panel);return panel;}
test('preview and Back retain selection, scroll and original dirty controls',async()=>{const x=await setup();try{enterSelection(x);const checkbox=x.d.querySelector('[data-wfb-select="s1"]');checkbox.click();x.d.querySelector('[data-wfb-preview="s1"]').click();assert.ok(x.d.querySelector('.wfb-preview'));x.d.querySelector('[data-wfb-action="back"]').click();assert.equal(x.d.querySelector('[data-wfb-select="s1"]').checked,true);assert.equal(x.d.querySelector('#original textarea').value,'Unsaved words');x.w.workbenchFolderBrowser.panelSpec('library').press('native');assert.equal(x.d.querySelector('.wfb-browser'),null);assert.equal(x.d.querySelector('#original textarea').value,'Unsaved words');}finally{x.close();}});
test('filing sends explicit actor, revision, hash, original IDs and fresh operation',async()=>{const x=await setup();try{enterSelection(x);x.d.querySelector('[data-wfb-select="s1"]').click();x.d.querySelector('[data-wfb-action="link"]').click();const target=x.d.querySelector('[data-wfb-destination]');target.value='b';x.d.querySelector('[data-wfb-action="apply"]').click();await new Promise(r=>setTimeout(r,10));const call=x.calls.find(c=>c.opts.method==='POST'),body=JSON.parse(call.opts.body);assert.equal(body.expectedRevision,1);assert.equal(body.expectedHash,'hash1');assert.deepEqual(body.sourceIds,['s1']);assert.equal(body.folderId,'b');assert.equal(call.opts.headers['X-AR-Actor'],'human:adrian');assert.equal(call.opts.headers['X-AR-Client'],'ui');assert.match(body.operationId,/^[a-f0-9-]{36}$/);}finally{x.close();}});
test('stale and offline writes preserve selection and show actionable error without retry',async()=>{const x=await setup(undefined,async()=>({ok:false,status:409,json:async()=>({error:'Changed elsewhere'})}));try{enterSelection(x);x.d.querySelector('[data-wfb-select="s1"]').click();x.d.querySelector('[data-wfb-action="undo"]').click();await new Promise(r=>setTimeout(r,10));assert.match(x.d.querySelector('[role="alert"]').textContent,/Refresh/);assert.equal(x.d.querySelector('[data-wfb-select="s1"]').checked,true);assert.equal(x.calls.filter(c=>c.opts.method==='POST').length,1);}finally{x.close();}});
test('search escapes untrusted source text and filters actual records',async()=>{const x=await setup(view([source('s1','<img src=x onerror=bad>'),source('s2','Beta') ]));try{assert.equal(x.d.querySelector('img[onerror]'),null);const q=x.d.querySelector('[data-wfb-search]');q.value='Beta';q.dispatchEvent(new x.w.Event('input',{bubbles:true}));assert.equal(x.d.querySelectorAll('.wfb-vrow').length,1);assert.equal(x.d.querySelector('.wfb-title').textContent,'Beta');}finally{x.close();}});
test('folder create, rename, nest and remove submit exact service actions',async()=>{const x=await setup();try{
 const api=x.w.workbenchFolderBrowser;api.panelSpec('library').press('folder:a');
 for(const [action,name] of [['new','New nested folder'],['rename','Renamed parent'],['reparent',null],['remove',null]]){
  const panel=mountFolderPanel(x);(panel.querySelector('[data-wfb-action="'+action+'"]')||panel.querySelector('[data-wfb-new]')).click();panel.remove();
  const input=x.d.querySelector('[data-wfb-name]');if(name)input.value=name;
  const select=x.d.querySelector('[data-wfb-destination]');if(select)select.value='';
  x.d.querySelector('[data-wfb-action="apply"]').click();await new Promise(r=>setTimeout(r,5));
 }
 const writes=x.calls.filter(c=>c.opts.method==='POST').map(c=>JSON.parse(c.opts.body));
 assert.deepEqual(writes.map(w=>w.action),['create','rename','reparent','remove']);
 assert.equal(writes[0].parentId,'a');assert.equal(writes[0].name,'New nested folder');
 assert.equal(writes[1].folderId,'a');assert.equal(writes[2].parentId,null);
 assert.equal(new Set(writes.map(w=>w.operationId)).size,4);
}finally{x.close();}});
test('Undo uses service persisted transaction identity and refreshed guards',async()=>{const x=await setup();try{x.d.querySelector('[data-wfb-action="undo"]').click();await new Promise(r=>setTimeout(r,5));const body=JSON.parse(x.calls.find(c=>c.opts.method==='POST').opts.body);assert.equal(body.action,'undo');assert.equal(body.undoOperationId,'undo1');assert.equal(body.expectedHash,'hash1');}finally{x.close();}});
test('offline refresh retains last known items and selected records',async()=>{const x=await setup();try{enterSelection(x);x.d.querySelector('[data-wfb-select="s1"]').click();x.w.fetch=async()=>{throw Error('Offline');};await x.w.workbenchFolderBrowser.refresh();assert.equal(x.d.querySelectorAll('.wfb-vrow').length,2);assert.equal(x.d.querySelector('[data-wfb-select="s1"]').checked,true);assert.match(x.d.querySelector('[role="alert"]').textContent,/refresh.*Offline/);}finally{x.close();}});
test('Media previews real blobs; This piece preserves contact sheet owner DOM',async()=>{const x=await setup();try{x.w.current=()=>({view:'record',viewedStage:8});x.w.fetch=async url=>({ok:true,json:async()=>url.includes('domain=media')?{...view([{id:'photo',title:'Real image',kind:'image'},{id:'video',title:'Real video',kind:'audio',rel_path:'clip.mp4'}]),domain:'media'}:view()});await x.w.workbenchFolderBrowser.refresh();x.w.workbenchFolderBrowser.panelSpec('media').press('all');x.d.querySelector('[data-wfb-preview="photo"]').click();assert.equal(x.d.querySelector('.wfb-mpv img').getAttribute('src'),'/api/sources/blob?id=photo');x.d.querySelector('[data-wfb-action="back"]').click();x.d.querySelector('[data-wfb-preview="video"]').click();assert.equal(x.d.querySelector('video').getAttribute('src'),'/api/sources/blob?id=video');x.w.workbenchFolderBrowser.panelSpec('media').press('native');assert.ok(x.d.querySelector('#original textarea'));assert.equal(x.d.querySelector('.wfb-browser'),null);}finally{x.close();}});
test('text preview reads existing source file endpoint and back restores actual list scroll',async()=>{const x=await setup(view(Array.from({length:200},(_,i)=>source('s'+i,String(i).padStart(3,'0')))));try{const list=x.d.querySelector('.wfb-vt');list.scrollTop=2400;list.dispatchEvent(new x.w.Event('scroll'));const id=x.d.querySelector('[data-wfb-preview]').dataset.wfbPreview;x.w.fetch=async url=>{assert.equal(url,'/api/sources/file?id='+id);return {ok:true,json:async()=>({text:'Actual readable source'})};};x.d.querySelector('[data-wfb-preview]').click();await new Promise(r=>setTimeout(r,5));assert.equal(x.d.querySelector('.wfb-reading').textContent,'Actual readable source');x.d.querySelector('[data-wfb-action="back"]').click();assert.equal(x.d.querySelector('.wfb-vt').scrollTop,2400);}finally{x.close();}});
test('repeated shell decoration is idempotent and never polls failed API',async()=>{const x=await setup();try{x.w.fetch=async()=>{throw Error('Offline');};await x.w.workbenchFolderBrowser.refresh();let requests=0;x.w.fetch=async()=>{requests++;throw Error('Offline');};const ws=x.d.querySelector('#workspace'),mutations=[];const observer=new x.w.MutationObserver(records=>mutations.push(...records));observer.observe(ws,{attributes:true,childList:true,subtree:true});const spec=x.w.workbenchFolderBrowser.panelSpec('library');for(let i=0;i<10;i++)spec.rows();await new Promise(r=>setTimeout(r,5));observer.disconnect();assert.equal(mutations.length,0);assert.equal(requests,0);}finally{x.close();}});
test('the real app lexical current binding mounts the browser and New folder form from Inbox',async()=>{
 const {Script}=await import('node:vm');const dom=new JSDOM('<div id="app"><div id="workspace"><h2 class="c3-ctitle">Library</h2></div></div>',{runScripts:'outside-only',url:'http://localhost/'}),w=dom.window;
 new Script("const current=()=>({view:'record',viewedStage:1})").runInContext(dom.getInternalVMContext());assert.equal(w.current,undefined);
 w.c3Shell={register(_name,fn){this.install=fn;}};w.c3Workbench={registerPanel(){},decorate(){}};w.fetch=async url=>({ok:true,json:async()=>({...view(),domain:url.includes('domain=media')?'media':'library'})});
 try{w.eval(await fs.readFile(new URL('../public/document-study/display-format.js',import.meta.url),'utf8'));w.eval(code);await w.workbenchFolderBrowser.refresh();const spec=w.workbenchFolderBrowser.panelSpec('library');const panel=w.document.createElement('aside');panel.innerHTML=spec.body(spec.rows());w.document.body.append(panel);spec.afterRender(panel);panel.querySelector('[data-wfb-new]').click();assert.ok(w.document.querySelector('.wfb-browser [data-wfb-name]'));}finally{w.close();}
});
test('counted facets and removable chips filter existing source facts',async()=>{const x=await setup(view([source('s1','Alpha'),source('s2','Beta','pdf') ]));try{x.d.querySelector('[data-wfb-action="filters"]').click();const facet=x.d.querySelector('[data-wfb-facet="type"]');assert.match(facet.textContent,/Note \(1\)/);assert.match(facet.textContent,/PDF \(1\)/);facet.value='pdf';facet.dispatchEvent(new x.w.Event('change',{bubbles:true}));assert.equal(x.d.querySelectorAll('.wfb-vrow').length,1);assert.match(x.d.querySelector('[data-wfb-clear="type"]').textContent,/PDF/);x.d.querySelector('[data-wfb-clear="type"]').click();assert.equal(x.d.querySelectorAll('.wfb-vrow').length,2);}finally{x.close();}});
test('Media grid keeps 2000 actual sources bounded and saved photo/video views honest',async()=>{const x=await setup();try{x.w.current=()=>({view:'record',viewedStage:8});const media={...view(Array.from({length:2000},(_,i)=>({id:'m'+i,title:String(i).padStart(4,'0'),kind:i===1999?'video':'image'}))),domain:'media'};x.w.fetch=async url=>({ok:true,json:async()=>url.includes('domain=media')?media:view()});await x.w.workbenchFolderBrowser.refresh();x.w.workbenchFolderBrowser.panelSpec('media').press('all');x.d.querySelector('[data-wfb-action="grid"]').click();assert.ok(x.d.querySelectorAll('.wfb-tile').length<50);const list=x.d.querySelector('.wfb-vt');list.scrollTop=parseFloat(list.querySelector('.wfb-vt-sp').style.height)-540;list.dispatchEvent(new x.w.Event('scroll'));assert.ok([...x.d.querySelectorAll('.wfb-title')].some(n=>n.textContent==='1999'));x.d.querySelector('[data-wfb-action="filters"]').click();const kindFilter=x.d.querySelector('[data-wfb-facet="type"]');kindFilter.value='video';kindFilter.dispatchEvent(new x.w.Event('change',{bubbles:true}));assert.equal(x.d.querySelectorAll('.wfb-tile').length,1);assert.match(x.d.querySelector('.wfb-count').textContent,/1 of 2000/);}finally{x.close();}});
test('Arrange photo picker reuses real Media data and returns exact source identity without writes',async()=>{const x=await setup();try{const host=x.d.createElement('div');x.d.body.append(host);const photos={...view([{id:'photo',title:'Actual photo',kind:'image'},{id:'clip',title:'A clip',kind:'video'}]),domain:'media'};x.w.fetch=async()=>({ok:true,json:async()=>photos});let selected;const picker=await x.w.workbenchFolderBrowser.mountPhotoPicker({container:host,onPick:p=>selected=p});assert.equal(host.querySelectorAll('.wfb-tile').length,1);assert.ok(host.querySelector('.wfb-picker-tree'));host.querySelector('[data-wfb-preview="photo"]').click();assert.equal(selected.sourceId,'photo');assert.equal(selected.url,'/api/sources/blob?id=photo');assert.equal(selected.source.title,'Actual photo');assert.equal(x.d.querySelector('#original textarea').value,'Unsaved words');assert.equal(x.calls.filter(c=>c.opts.method==='POST').length,0);picker.destroy();assert.equal(host.children.length,0);}finally{x.close();}});
test('shift selection includes the actual intervening rows',async()=>{const x=await setup(view([source('s1','Alpha'),source('s2','Beta'),source('s3','Gamma') ]));try{enterSelection(x);x.d.querySelector('[data-wfb-select="s1"]').click();x.d.querySelector('[data-wfb-select="s3"]').dispatchEvent(new x.w.MouseEvent('click',{bubbles:true,shiftKey:true}));assert.equal(x.d.querySelectorAll('[data-wfb-select]:checked').length,3);}finally{x.close();}});
test('photo picker fills bounded available images and updates remaining slots without remount',async()=>{const x=await setup();try{const host=x.d.createElement('div');x.d.body.append(host);x.w.fetch=async()=>({ok:true,json:async()=>({...view([{id:'p1',title:'One',kind:'image'},{id:'p2',title:'Two',kind:'image'},{id:'v',title:'Video',kind:'video'}]),domain:'media'})});let picked;const picker=await x.w.workbenchFolderBrowser.mountPhotoPicker({container:host,onPick(){},onPickMany:items=>picked=items,maxPick:2});host.querySelector('[data-wfb-all]').click();assert.match(host.querySelector('[data-wfb-action="fillphotos"]').textContent,/Fill 2/);const node=host.querySelector('.wfb-browser');picker.setMaxPick(1);assert.equal(host.querySelector('.wfb-browser'),node);host.querySelector('[data-wfb-action="fillphotos"]').click();assert.equal(picked.length,1);assert.equal(picked[0].source.kind,'image');picker.destroy();}finally{x.close();}});
test('column sorting reverses and Source sorting uses the actual publication',async()=>{const x=await setup(view([{...source('s1','Alpha'),publication:'Zulu'},{...source('s2','Beta'),publication:'Atlas'}]));try{x.d.querySelector('[data-wfb-order="title"]').click();assert.equal(x.d.querySelector('.wfb-title').textContent,'Alpha');x.d.querySelector('[data-wfb-order="title"]').click();assert.equal(x.d.querySelector('.wfb-title').textContent,'Beta');assert.equal(x.d.querySelector('[data-wfb-order="title"]').getAttribute('aria-label'),'Title, descending; sort ascending');x.d.querySelector('[data-wfb-order="source"]').click();assert.equal(x.d.querySelector('.wfb-title').textContent,'Beta');x.d.querySelector('[data-wfb-order="source"]').click();assert.equal(x.d.querySelector('.wfb-title').textContent,'Alpha');}finally{x.close();}});
test('picker breadcrumbs keep browse navigation unchanged and preserve selected photos',async()=>{const x=await setup();try{const host=x.d.createElement('div');x.d.body.append(host);x.w.localStorage.setItem('workbench-folders-nav-media','unchanged');x.w.fetch=async()=>({ok:true,json:async()=>({...view([{id:'s1',title:'Photo',kind:'image'}]),domain:'media'})});const picker=await x.w.workbenchFolderBrowser.mountPhotoPicker({container:host,folderId:'b',onPick(){}});host.querySelector('[data-wfb-select="s1"]').click();host.querySelector('[data-wfb-folder-pick="all"]').click();assert.equal(host.querySelector('[data-wfb-select="s1"]').checked,true);assert.equal(host.querySelectorAll('.wfb-picker-tree [aria-current="true"]').length,1);assert.equal(host.querySelector('.wfb-picker-tree [aria-current="true"]').dataset.wbRow,'all');assert.equal(x.w.localStorage.getItem('workbench-folders-nav-media'),'unchanged');picker.destroy();picker.setMaxPick(3);assert.equal(host.childElementCount,0);x.w.dispatchEvent(new x.w.Event('resize'));assert.equal(host.childElementCount,0);}finally{x.close();}});
test('picker bulk fill follows selection order and clamps the latest slot count',async()=>{const x=await setup();try{const host=x.d.createElement('div');x.d.body.append(host);x.w.fetch=async()=>({ok:true,json:async()=>({...view([{id:'p1',title:'One',kind:'image'},{id:'p2',title:'Two',kind:'image'}]),domain:'media'})});let picked;const picker=await x.w.workbenchFolderBrowser.mountPhotoPicker({container:host,onPick(){},onPickMany:p=>picked=p,maxPick:2});host.querySelector('[data-wfb-select="p2"]').click();host.querySelector('[data-wfb-select="p1"]').click();picker.setMaxPick(1.9);host.querySelector('[data-wfb-action="fillphotos"]').click();assert.equal(picked.length,1);assert.equal(picked[0].id,'p2');picker.setMaxPick(0);assert.equal(host.querySelector('[data-wfb-action="fillphotos"]').disabled,true);picker.destroy();}finally{x.close();}});
test('closing a photo host while its source request is pending never resurrects the picker',async()=>{const x=await setup();try{const host=x.d.createElement('div');x.d.body.append(host);let release;x.w.fetch=()=>new Promise(resolve=>release=resolve);const pending=x.w.workbenchFolderBrowser.mountPhotoPicker({container:host,onPick(){}});host.remove();release({ok:true,json:async()=>({...view([{id:'p1',title:'Photo',kind:'image'}]),domain:'media'})});const picker=await pending;assert.equal(x.d.querySelector('.wfb-picker-shell'),null);picker.destroy();x.w.dispatchEvent(new x.w.Event('resize'));assert.equal(x.d.querySelector('.wfb-picker-shell'),null);}finally{x.close();}});

const usageRoot='11111111-1111-4111-8111-111111111111',usageHash='a'.repeat(64),pause=()=>new Promise(resolve=>setTimeout(resolve,8));
function usageView(input,{complete=true,occurrences={},status='available'}={}){return {schema:'ar-create.media-usage.v1',scope:{rootBindingId:input.rootBindingId,parentStudyId:input.parentStudyId},usageHash,coverage:{complete,status:complete?'complete':'partial'},sources:input.sourceIds.map(sourceId=>({sourceId,status,occurrences:occurrences[sourceId]||[]}))};}
const usageOccurrence=(sourceId='p1',parentStudyId='hk')=>({id:'occurrence-one',sourceId,scope:{rootBindingId:usageRoot,parentStudyId},outputId:'saved-carousel',outputName:'Saved carousel',kind:'carousel',location:{slideId:'stable-slide',slideNumber:3,photoIndex:1,photoNumber:2},caption:'Saved caption',credit:'Saved credit'});
async function usageSetup(read,rows=[{id:'p1',title:'One',kind:'image'},{id:'p2',title:'Two',kind:'image'}]){const x=await setup();x.w.current=()=>({id:'hk',view:'record',viewedStage:8});x.w.studyDraft={currentBinding:()=>({id:usageRoot,parentStudyId:'hk',kind:'primary'})};x.w.studyOutputConnection={selection:()=>null};x.w.studyMediaUsage={read,open:async()=>{}};x.w.fetch=async()=>({ok:true,json:async()=>({...view(rows),domain:'media',folders:[{id:'a',name:'Original folder',parentId:null,sourceIds:['p1']} ]})});await x.w.workbenchFolderBrowser.refresh();x.w.workbenchFolderBrowser.panelSpec('media').press('all');await pause();return x;}

test('Media uses the existing saved usage reader/open owner with exact scope and retains original membership',async()=>{const reads=[],opened=[],occurrence=usageOccurrence();const x=await usageSetup(async input=>{reads.push(input);return usageView(input,{occurrences:{p1:[occurrence]}});});try{x.w.studyMediaUsage.open=async(...args)=>opened.push(args);assert.equal(reads.length,1);assert.equal(reads[0].parentStudyId,'hk');assert.equal(reads[0].rootBindingId,usageRoot);assert.deepEqual(Array.from(reads[0].sourceIds),['p1','p2']);assert.equal(x.d.querySelector('[data-wfb-usage="p1"]').textContent,'1 in project');assert.equal(x.d.querySelector('[data-wfb-usage="p2"]').textContent,'0 in project');assert.match(x.d.querySelector('[data-wfb-usage="p2"]').title,/Global usage is unknown/);x.d.querySelector('[data-wfb-preview="p1"]').click();assert.match(x.d.querySelector('.wfb-usages').textContent,/Slide 3 · photo 2/);assert.match(x.d.querySelector('.wfb-usages').textContent,/Saved caption/);assert.match(x.d.querySelector('.wfb-usages').textContent,/Saved credit/);assert.match(x.d.querySelector('.wfb-memberships').textContent,/Original folder/);x.d.querySelector('[data-wfb-usage-open]').click();await pause();assert.equal(opened.length,1);assert.deepEqual(JSON.parse(JSON.stringify(opened[0])),[occurrence,usageHash]);assert.equal(x.calls.filter(call=>call.opts.method==='POST').length,0);x.d.querySelector('[data-wfb-action="back"]').click();x.d.querySelector('[data-wfb-action="filters"]').click();assert.equal(x.d.querySelector('[aria-label="Used"]'),null);assert.equal(x.d.querySelector('.wfb-views'),null);x.d.querySelector('[data-wfb-action="media-actions"]').click();assert.match(x.d.querySelector('.wfb-media-help').textContent,/Selecting a photograph does not place/);x.d.querySelector('[data-wfb-action="media-list"]').click();assert.ok(x.d.querySelector('[data-wfb-search]'));}finally{x.close();}});

test('partial, unavailable and missing usage evidence never manufactures global unused',async()=>{let mode='partial';const x=await usageSetup(async input=>mode==='missing'?{...usageView(input),sources:[]}:usageView(input,{complete:false,status:mode==='unavailable'?'unavailable':'available'}));try{assert.equal(x.d.querySelector('[data-wfb-usage="p1"]').textContent,'Unknown');x.d.querySelector('[data-wfb-preview="p1"]').click();assert.match(x.d.querySelector('.wfb-usages').textContent,/Coverage is partial|other uses remain unknown/);for(const value of ['unavailable','missing']){mode=value;x.w.dispatchEvent(new x.w.Event('study-output-saved'));await pause();assert.match(x.d.querySelector('.wfb-usages').textContent,/partial|unavailable/);assert.doesNotMatch(x.d.querySelector('.wfb-usages').textContent,/No saved placements in this project/);}assert.match(x.d.querySelector('.wfb-usages').textContent,/did not match/);assert.match(x.d.querySelector('.wfb-memberships').textContent,/Original folder/);}finally{x.close();}});

test('usage reads are bounded to visible assets and never scan 2000 sources eagerly',async()=>{const calls=[];const x=await usageSetup(async input=>{calls.push(input);return usageView(input);},Array.from({length:2000},(_,i)=>({id:'p'+i,title:String(i).padStart(4,'0'),kind:'image'})));try{assert.ok(calls.length>=1);assert.ok(calls.every(call=>call.sourceIds.length<=200));assert.ok(calls.flatMap(call=>call.sourceIds).length<100);const list=x.d.querySelector('.wfb-vt');list.scrollTop=1990*36;list.dispatchEvent(new x.w.Event('scroll'));await pause();assert.ok(calls.some(call=>call.sourceIds.includes('p1999')));assert.ok(calls.flatMap(call=>call.sourceIds).length<200);}finally{x.close();}});

test('cross-project replies and scope changes refuse usage without changing source folders',async()=>{let release;const x=await usageSetup(input=>new Promise(resolve=>release=()=>resolve(usageView(input,{occurrences:{p1:[usageOccurrence()]}}))));try{x.d.querySelector('[data-wfb-preview="p1"]').click();x.w.current=()=>({id:'another-story',view:'record',viewedStage:8});x.w.dispatchEvent(new x.w.Event('study-draft-change'));release();await pause();assert.equal(x.d.querySelector('[data-wfb-usage-open]'),null);assert.match(x.d.querySelector('.wfb-usages').textContent,/Choose an owned working manuscript/);assert.match(x.d.querySelector('.wfb-memberships').textContent,/Original folder/);x.w.current=()=>({id:'hk',view:'record',viewedStage:8});x.w.studyMediaUsage.read=async input=>({...usageView(input),scope:{rootBindingId:usageRoot,parentStudyId:'another-story'}});x.w.dispatchEvent(new x.w.Event('study-output-saved'));await pause();assert.equal(x.d.querySelector('[data-wfb-usage-open]'),null);assert.match(x.d.querySelector('.wfb-usages').textContent,/did not match/);}finally{x.close();}});

test('late usage reads cannot reopen a closed preview; output-save invalidation replaces cached proof',async()=>{let release,phase='waiting',reads=0;const x=await usageSetup(input=>{reads++;return phase==='waiting'?new Promise(resolve=>release=()=>resolve(usageView(input,{occurrences:{p1:[usageOccurrence()]}}))):Promise.resolve(usageView(input));});try{x.d.querySelector('[data-wfb-preview="p1"]').click();x.d.querySelector('[data-wfb-action="back"]').click();release();await pause();assert.equal(x.d.querySelector('.wfb-preview'),null);assert.equal(x.d.querySelector('[data-wfb-usage="p1"]').textContent,'1 in project');phase='saved';x.w.dispatchEvent(new x.w.Event('study-output-saved'));await pause();assert.equal(x.d.querySelector('[data-wfb-usage="p1"]').textContent,'0 in project');assert.equal(reads,2);for(let i=0;i<5;i++)x.w.dispatchEvent(new x.w.Event('study-draft-change'));await pause();assert.equal(reads,2,'typing the same binding does not poll usage');}finally{x.close();}});

test('missing owner context does not read usage, and exact matching output selection supplies its real root',async()=>{const calls=[];const x=await usageSetup(async input=>{calls.push(input);return usageView(input);});try{x.w.studyDraft.currentBinding=()=>({id:usageRoot,parentStudyId:'another-story'});x.w.studyOutputConnection.selection=()=>({projectId:'another-story',rootBindingId:usageRoot});x.w.dispatchEvent(new x.w.Event('study-output-selection'));await pause();assert.equal(calls.length,1);assert.equal(x.d.querySelector('[data-wfb-usage="p1"]').textContent,'Unknown');const actualRoot='22222222-2222-4222-8222-222222222222';x.w.studyOutputConnection.selection=()=>({projectId:'hk',rootBindingId:actualRoot,output:{id:'exact-output'}});x.w.dispatchEvent(new x.w.Event('study-output-selection'));await pause();assert.equal(calls.at(-1).rootBindingId,actualRoot);assert.equal(calls.at(-1).parentStudyId,'hk');delete x.w.studyMediaUsage;x.d.querySelector('[data-wfb-preview="p1"]').click();x.w.dispatchEvent(new x.w.Event('study-output-saved'));assert.match(x.d.querySelector('.wfb-usages').textContent,/reader is unavailable/);}finally{x.close();}});

test('a stale guarded Open reports its refusal and explicit Refresh reads new usage without filing changes',async()=>{let reads=0;const x=await usageSetup(async input=>{reads++;return usageView(input,{occurrences:{p1:[usageOccurrence()]}});});try{x.w.studyMediaUsage.open=async()=>{throw Error('Media usage changed; refresh this occurrence before navigation.');};x.d.querySelector('[data-wfb-preview="p1"]').click();x.d.querySelector('[data-wfb-usage-open]').click();await pause();assert.match(x.d.querySelector('.wfb-usages [role="status"]').textContent,/usage changed/);x.d.querySelector('[data-wfb-usage-refresh]').click();await pause();assert.equal(reads,2);assert.match(x.d.querySelector('.wfb-memberships').textContent,/Original folder/);assert.equal(x.calls.filter(call=>call.opts.method==='POST').length,0);}finally{x.close();}});

test('existing canvas save proof invalidates cached usage through shell decoration without polling',async()=>{const callbacks=[];let reads=0,pending=false,token=null;const dom=new JSDOM('<div id="app"><div id="workspace"></div></div>',{runScripts:'outside-only',url:'http://localhost/'}),w=dom.window;w.current=()=>({id:'hk',view:'record',viewedStage:8});w.matchMedia=()=>({matches:false});w.studyDraft={currentBinding:()=>({id:usageRoot,parentStudyId:'hk'})};w.studyOutputConnection={selection:()=>null,canvasProof:()=>({scope:{parentStudyId:'hk',rootBindingId:usageRoot},selectedOutputId:'saved',pending,browserDraftToken:token})};w.c3Shell={register(name,callback){callbacks.push(callback);}};w.c3Workbench={registerPanel(){},decorate(){}};w.fetch=async url=>({ok:true,json:async()=>({...view([{id:'p1',title:'Photo',kind:'image'}]),domain:url.includes('domain=media')?'media':'library'})});w.studyMediaUsage={read:async input=>{reads++;return usageView(input);}};try{w.eval(await fs.readFile(new URL('../public/document-study/display-format.js',import.meta.url),'utf8'));w.eval(code);await w.workbenchFolderBrowser.refresh();w.workbenchFolderBrowser.panelSpec('media').press('all');await pause();assert.equal(reads,1);for(let i=0;i<6;i++)callbacks[0]();await pause();assert.equal(reads,1);pending=true;token='edited';callbacks[0]();await pause();assert.equal(reads,2);pending=false;token=null;callbacks[0]();await pause();assert.equal(reads,3,'save completion gets fresh saved evidence through existing canvas proof');}finally{w.close();}});

