test('folder navigation keeps the saved-view marker aligned with the actual scope without source writes',async()=>{
 const x=await setup(view([source('s1','Alpha'),source('s2','Beta'),source('s3','Unfiled')]));try{x.d.querySelector('[data-wfb-action=filters]').click();
  x.d.querySelector('[data-wfb-view="unsorted"]').click();
  assert.equal(x.d.querySelector('[data-wfb-view="unsorted"]').getAttribute('aria-current'),'page');
  x.w.workbenchFolderBrowser.panelSpec('library').press('all');
  assert.equal(x.d.querySelector('[data-wfb-view="all"]').getAttribute('aria-current'),'page','All sources must mark All, not a stale Unsorted saved view');
  assert.equal(x.d.querySelector('[data-wfb-view="unsorted"]').hasAttribute('aria-current'),false);
  assert.equal(x.d.querySelectorAll('.wfb-vrow').length,3);
  x.w.workbenchFolderBrowser.panelSpec('library').press('folder:a');
  assert.equal(x.d.querySelector('.wfb-views [aria-current]'),null,'a named folder is not a global saved view');
  x.w.workbenchFolderBrowser.panelSpec('library').press('unsorted');
  assert.equal(x.d.querySelector('[data-wfb-view="unsorted"]').getAttribute('aria-current'),'page');
  assert.equal(x.calls.filter(c=>c.opts.method==='POST').length,0);
 }finally{x.close();}
});

